//! Parity tests against the Go original (`github.com/junhinhow/charm-toast`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-toast/cmd/parity`:
//!
//! ```text
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-toast/tests/golden/toast.txt -- \
//!     go run ./reference/go/charm-toast/cmd/parity
//! ```
//!
//! [`build_report`] mirrors that Go program line by line, so the two outputs
//! must match after ANSI codes are removed.

use std::fmt::Write as _;
use std::time::Duration;

use charm_parity::assert_golden;
use charm_toast::{Toast, ToastManager, ToastType};

/// Every severity, in the same order as the Go parity program.
const TYPES: [ToastType; 4] = [
    ToastType::Info,
    ToastType::Success,
    ToastType::Warning,
    ToastType::Error,
];

/// Builds the human readable report, mirroring the Go parity program.
fn build_report() -> String {
    let mut out = String::new();

    for kind in TYPES {
        let _ = writeln!(
            out,
            "type={} icon={} color={}",
            kind.label(),
            kind.icon(),
            kind.color().to_hex()
        );
    }

    for kind in TYPES {
        let toast = Toast::new("Operacao concluida", Duration::from_secs(60)).with_type(kind);
        let _ = writeln!(out, "== render {} ==", kind.label());
        let _ = writeln!(out, "{}", toast.render(0));
        let _ = writeln!(out, "{}", toast.render(40));
    }

    let mut manager = ToastManager::new();
    manager.add_info("Notificacao 1", Duration::from_secs(60));
    manager.add_success("Notificacao 2", Duration::from_secs(60));
    manager.add_warning("Aviso", Duration::from_secs(60));
    manager.add_error("Erro", Duration::from_secs(60));
    let _ = writeln!(out, "count={} max={}", manager.count(), manager.max_visible);
    let _ = writeln!(out, "== manager ==");
    let _ = writeln!(out, "{}", manager.render(60));

    manager.max_visible = 2;
    let _ = writeln!(out, "== manager max=2 ==");
    let _ = writeln!(out, "{}", manager.render(60));

    manager.clear();
    let _ = writeln!(out, "== manager empty ==");
    let _ = writeln!(out, "[{}]", manager.render(60));
    let _ = writeln!(out, "count={}", manager.count());

    out
}

#[test]
fn toast_report_matches_go() {
    assert_golden("toast", &build_report());
}
